static int sctp_stream_alloc_in(struct sctp_stream *stream, __u16 incnt,
				gfp_t gfp)
{
	struct flex_array *in;
	size_t elem_size = sizeof(struct sctp_stream_in);

	in = fa_alloc(elem_size, incnt, gfp);
	if (!in)
		return -ENOMEM;

